import { useState } from 'react';
import api from '../api';

function Register() {
  const [role, setRole] = useState('STUDENT');
  const [msg, setMsg] = useState('');

  const [form, setForm] = useState({
    email: '',
    phone: '',
    password: '',
    full_name: '',
    department: '',
    batch: '',
    company: '',
    designation: ''
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleRegister = async (e) => {
    e.preventDefault();

    try {
      const res = await api.post('/register', {
        ...form,
        role
      });
      setMsg(res.data);
    } catch {
      setMsg('Registration failed');
    }
  };
  const password = form.password;

const passwordValid =
  password.length >= 8 &&
  /[A-Z]/.test(password) &&
  /[a-z]/.test(password) &&
  /\d/.test(password) &&
  /[@$!%*?&]/.test(password);

if (!passwordValid) {
  setMsg('Password must be strong');
  return;
}


  return (
    <div>
      <h2>Register</h2>

      <form onSubmit={handleRegister}>
        <input name="email" placeholder="Email" onChange={(e) => {if (!form.email.includes('@') || !form.email.includes('.')) {
        setMsg('Enter a valid email');return;}handleChange(e)}} required />

        <input name="phone" placeholder="Phone" value={form.phone} onChange={(e) => {if (/^\d*$/.test(e.target.value)) 
        {handleChange(e);}}}required/>

        <input name="password" type="password" placeholder="Password" onChange={handleChange} required />

        <select onChange={(e) => setRole(e.target.value)}>
          <option value="STUDENT">Student</option>
          <option value="ALUMNI">Alumni</option>
        </select>

        <input name="full_name" placeholder="Full Name" onChange={handleChange} required />
        <input name="department" placeholder="Department" onChange={handleChange} required />
        <input name="batch" placeholder="Batch" onChange={handleChange} required />

        {role === 'ALUMNI' && (
          <>
            <input name="company" placeholder="Company" onChange={handleChange} />
            <input name="designation" placeholder="Designation" onChange={handleChange} />
          </>
        )}

        <button type="submit">Register</button>
      </form>

      {msg && <p>{msg}</p>}
    </div>
  );
}

export default Register;
